            options = []
            # Option0: do nothing
            options.append((0, 0, x))
            # Option1: apply Op1
            v1 = (x + 1) // 2
            options.append((1, 0, v1))
            # Option2: apply Op2 if possible
            if x >= k_val:
                v2 = x - k_val
                options.append((0, 1, v2))
